import{_ as p,a0 as R,w as n,s as l,ao as d,I as r,a1 as a,A as o,x as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"Red Hat 為64位ARM服務器做準備 | LCTT x X-CMD","titleTemplate":false,"description":"Red Hat 為64位ARM服務器做準備 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Red Hat 為64位ARM服務器做準備 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Red Hat 為64位ARM服務器做準備 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/Red Hat prepares for 64-bit ARM servers","title":"Red Hat 為64位ARM服務器做準備","tag":"201311","desc":""},"relativePath":"201311/Red Hat prepares for 64-bit ARM servers.md","filePath":"[post].md"}'),M={name:"201311/Red Hat prepares for 64-bit ARM servers.md"};function i(A,t,u,m,f,T){const s=R("Link");return n(),l("div",null,[t[13]||(t[13]=d('<h1 id="red-hat-為64位arm服務器做準備" tabindex="-1">Red Hat 為64位ARM服務器做準備 <a class="header-anchor" href="#red-hat-為64位arm服務器做準備" aria-label="Permalink to “Red Hat 為64位ARM服務器做準備”">​</a></h1><blockquote><p>ARM處理器可能帶來具有成千上萬的節點的堆疊服務器，Red Hat的ARM首席架構師預測説</p></blockquote><p>來自IDG新聞服務：企業開源軟件供應商Red Hat公司正在密切關注服務器的64位ARM處理器的發展，以建立在數據中心的新生平台上的專業能力。</p><p>“你們在當今的商業產品市場看不到我們，但我們已經建立了超越如今一些64位技術的能力。所以接下來，如果我們有一個需要應對的市場，我們將有能力應對，”Red Hat首席ARM設計師Jon Masters説。這是Masters週五在華盛頓特區舉行的USENIX LISA（大型安裝系統管理）會議上提出的。</p><p>ARM處理器代表了“計算上翻天覆地的變化，”Masters説。雖然已經在智能手機和嵌入式計算設備佔據主導地位，ARM處理器架構還可以在數據中心發揮作用。在過去的一年中，基於ARM處理器的服務器已經開始出現在服務器市場。惠普已經開始銷售基於ARM架構的Moonshot系列服務器。</p><p>對於數據中心，ARM可能會因其低功耗設計而帶來超大規模計算時代，這樣數千個微型計算節點可以打包成一個堆疊服務器。“我們在不久的將來能夠建立起完全區別於現今的規模。”Masters説。</p><p>ARM處理器可能無法以x86處理器的速度運行，但它們可以提供大部分的性能而只消耗一小部分能源，這意味着在一個較小的空間可以打包更多的處理器。“你可以用你手機中相同的技術，作為高密度服務器設計的一部分”，Masters説。</p><p>他説，許多工作並不需要最快的處理器。相反，工作負載可以分佈在更多的處理器上。“這和我能移動多少數據有關係，並不一定和我能做多少計算有關，”他説。例如，雲計算和Web應用程序運行在多個服務器上，和運行在數量較少但速度更快的服務器上的表現會同樣出色。</p><p>ARM的設計也可以簡化數據中心操作。ARM的芯片內系統的設計方式可以解決管理許多服務器的外部元件的需要。例如，ARM處理器可以提供交叉互聯，減少外部電纜和頂級機架交換機的需要。</p><p>“每一個刀片都具有離散佈線已經指日可待了， ”他説。</p><p>Masters説超大規模計算還需要做大量的工作。</p><p>ARM授權它的架構而不是和英特爾一樣賣處理器。其結果是，從不同供應商提供的不同的ARM處理器有相當程度的變化。“有很多我們不需要的，不必要的變化，”Masters説。 ”這可能成為需要統一系統來管理集體的數據中心的一個問題。</p>',12)),r("p",null,[a(s,{href:"http://www.linaro.org/"},{default:o(()=>[...t[0]||(t[0]=[e("Linaro",-1)])]),_:1}),t[1]||(t[1]=e("是一個致力於為ARM平台和部分已經標準化ARM任務開發核心開源軟件的產業羣。Red Hat的工程師發揮了重要作用，Linaro企業集團，或稱為LEG，一直在努力規範軟件，讓用户可以得到一個能運行在不同供應商提供的ARM處理器的Linux版本。”這些都是在企業領域的基本期望，”Masters説。",-1))]),t[14]||(t[14]=r("p",null,"“我們需要把重心放在如何使它們從根本上兼容，這樣你可以進一步增加堆疊，”他説。",-1)),t[15]||(t[15]=r("p",null,"另一個問題是對外圍設備的支持，仍然沒有標準化的32位ARM處理器。Masters説，LEG正在考慮使用64位ARM處理器的ACPI（高級配置和電源接口）標準或UEFI（統一可擴展固件接口）。隨着時間的推移，ARM將提供一個類似自動化總線的能力，比如將提供支持x86的機器的PCI總線。",-1)),t[16]||(t[16]=r("p",null,"Masters説，Red Hat還沒有宣佈任何關於什麼時候會發佈一個ARM架構的Red Hat企業Linux版本的通知，但他明確指出，測試了許多RHEL應用程序的社區Linux發行版Fedora項目，現在已經為ARM提供了一個發行版。",-1)),t[17]||(t[17]=r("hr",null,null,-1)),r("p",null,[t[3]||(t[3]=e("via: ",-1)),a(s,{href:"http://www.computerworld.com/s/article/9243921/Red_Hat_prepares_for_64_bit_ARM_servers?taxonomyId=122"},{default:o(()=>[...t[2]||(t[2]=[e("http://www.computerworld.com/s/article/9243921/Red_Hat_prepares_for_64_bit_ARM_servers?taxonomyId=122",-1)])]),_:1})]),r("p",null,[t[6]||(t[6]=e("譯者：",-1)),a(s,{href:"https://github.com/whatever1992"},{default:o(()=>[...t[4]||(t[4]=[e("whatever1992",-1)])]),_:1}),t[7]||(t[7]=e(" 校對：",-1)),a(s,{href:"https://github.com/wxy"},{default:o(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[10]||(t[10]=e("本文由 ",-1)),a(s,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原創翻譯，",-1)),a(s,{href:"http://linux.cn/"},{default:o(()=>[...t[9]||(t[9]=[e("Linux中國",-1)])]),_:1}),t[12]||(t[12]=e(" 榮譽推出",-1))])])}const C=p(M,[["render",i]]);export{L as __pageData,C as default};
